//! UV theory fraction comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_uv_phi.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::ljs::{uv_phi, uv_phi_temp};

const ATOL: f64 = 1.0e-14;
const RTOL: f64 = 1.0e-12;

#[test]
fn uv_fractions_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/uv_phi.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let eps_divk: f64 = parts[0].parse().unwrap();
        let temperature: f64 = parts[1].parse().unwrap();
        let rho: f64 = parts[2].parse().unwrap();
        let source: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let native = uv_phi(eps_divk, temperature, rho);
        let native = [native.0, native.1, native.2, native.3, native.4, native.5];
        assert_eq!(native.len(), source.len(), "{case}");
        for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "{case} entry {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 5);
}

#[test]
fn the_temperature_dependent_fraction_carries_the_derivatives() {
    // The temperature dependent form of the source adds the derivatives with
    // respect to the temperature, and its fraction agrees with the plain form
    // at the reduced density of the source.
    let eps_divk = 124.0;
    let temperature = 200.0;
    let rho = 0.8;
    let (value, value_r, value_t, value_rr, value_tt, value_rt) =
        uv_phi_temp(eps_divk, temperature, rho);
    assert!(value.is_finite() && value_r.is_finite());
    assert!(value_rr.is_finite() && value_tt.is_finite() && value_rt.is_finite());
    // The plain form of the source does not depend on the temperature.
    let (_, plain_r, plain_t, _, plain_tt, plain_rt) = uv_phi(eps_divk, temperature, rho);
    assert!((plain_t - 0.0).abs() < 1.0e-30);
    assert!((plain_tt - 0.0).abs() < 1.0e-30);
    assert!((plain_rt - 0.0).abs() < 1.0e-30);
    assert!(value_t.abs() > 0.0);
    assert!(plain_r != value_r);
}
